"use client";

import { X } from "lucide-react";
import { useId, type ComponentProps, type ReactNode } from "react";
import { Button } from "./button";
import { FeedbackIcon, type FeedbackVariant } from "./feedback";
import { cn } from "./lib/cn";
import "./shared/alert.css";
import "./alert.css";

export type AlertProps = Omit<ComponentProps<"div">, "title"> & {
  title: ReactNode;
  variant?: FeedbackVariant;
  loading?: boolean;
  action?: ReactNode;
  onDismiss?: () => void;
};

export function Alert({
  title,
  variant = "neutral",
  loading = false,
  children,
  action,
  onDismiss,
  className,
  ...props
}: AlertProps) {
  const titleId = useId();
  return (
    <div
      data-slot="alert"
      data-variant={loading ? "neutral" : variant}
      role={!loading && variant === "error" ? "alert" : "status"}
      aria-busy={loading || undefined}
      aria-atomic="true"
      aria-labelledby={titleId}
      className={cn(
        "grid min-w-0 grid-cols-[2rem_minmax(0,1fr)_auto] items-start gap-3 rounded-overlay border border-border bg-surface p-4 text-sm text-foreground [overflow-wrap:anywhere]",
        className,
      )}
      {...props}
    >
      <FeedbackIcon variant={variant} loading={loading} />
      <div data-slot="feedback-copy" className="min-w-0 pt-1">
        <div id={titleId} data-slot="feedback-title" className="font-semibold leading-5">
          <span key={loading ? "loading" : variant} data-slot="feedback-message">{title}</span>
        </div>
        {children != null && (
          <div data-slot="feedback-description" className="mt-1 text-sm leading-5 text-muted-foreground">
            <span key={loading ? "loading" : variant} data-slot="feedback-message">{children}</span>
          </div>
        )}
        {action != null && (
          <div data-slot="feedback-action" className="mt-3 flex max-w-full flex-wrap items-center gap-2">
            {action}
          </div>
        )}
      </div>
      {onDismiss && (
        <Button
          variant="ghost"
          size="icon"
          className="-mt-1 -mr-1"
          aria-label="Dismiss alert"
          onClick={onDismiss}
        >
          <X aria-hidden="true" />
        </Button>
      )}
    </div>
  );
}

"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

"use client";
import { CheckCircle2 } from "lucide-react";
import { useEffect, useId, useRef, useState, type FormEvent } from "react";
import { Alert } from "./alert";
import { Button } from "./button";
import { Field, isEmail } from "./field";
import { Input } from "./input";
import { cn } from "./lib/cn";
import { SelectMenu } from "./select-menu";
import { Textarea } from "./textarea";

export type ContactDetail = { label: string; value: string; href?: string };
export type ContactResult = void | { error?: string; fields?: { name?: string; email?: string; message?: string } };

/** A contact form beside a few direct ways to reach you. It sends nothing itself and keeps the message if sending fails. */
export function ContactSection({
  title = "Contact us",
  description,
  details,
  topics,
  onSubmit,
  successTitle = "Message sent",
  successText = "Thanks. We will reply within one business day.",
  className,
}: {
  title?: string;
  description?: string;
  details?: readonly ContactDetail[];
  topics?: readonly string[];
  onSubmit: (values: { name: string; email: string; topic: string; message: string }) => Promise<ContactResult> | ContactResult;
  successTitle?: string;
  successText?: string;
  className?: string;
}) {
  const [values, setValues] = useState({ name: "", email: "", topic: topics?.[0] ?? "", message: "", website: "" });
  const [touched, setTouched] = useState({ name: false, email: false, message: false });
  const [server, setServer] = useState<{ error?: string; fields?: { name?: string; email?: string; message?: string } }>({});
  const [pending, setPending] = useState(false),
    [sent, setSent] = useState(false);
  const form = useRef<HTMLFormElement>(null);
  const refocus = useRef<string | null>(null);
  const heading = useId();
  const thanks = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (pending || !refocus.current) return;
    form.current?.querySelector<HTMLElement>(`[name="${refocus.current}"]`)?.focus();
    refocus.current = null;
  }, [pending]);
  useEffect(() => {
    if (sent) thanks.current?.focus();
  }, [sent]);

  const local = {
    name: !values.name.trim() ? "Tell us your name." : "",
    email: !values.email.trim() ? "Enter your email address." : !isEmail(values.email) ? "Enter a valid email address, like name@example.com." : "",
    message: values.message.trim().length < 10 ? "Write a few words about what you need (at least 10 characters)." : "",
  };
  const errors = {
    name: (touched.name && local.name) || server.fields?.name || "",
    email: (touched.email && local.email) || server.fields?.email || "",
    message: (touched.message && local.message) || server.fields?.message || "",
  };

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    if (pending) return;
    setTouched({ name: true, email: true, message: true });
    setServer({});
    const first = (["name", "email", "message"] as const).find((k) => local[k]);
    if (first) {
      form.current?.querySelector<HTMLElement>(`[name="${first}"]`)?.focus();
      return;
    }
    // Real people never see the hidden field; if it has text, pretend it worked.
    if (values.website) {
      setSent(true);
      return;
    }
    setPending(true);
    let target: string | undefined;
    try {
      const result = await onSubmit({ name: values.name.trim(), email: values.email.trim(), topic: values.topic, message: values.message.trim() });
      if (result && (result.error || result.fields)) {
        setServer(result);
        target = (["name", "email", "message"] as const).find((k) => result.fields?.[k]);
      } else setSent(true);
    } catch (error) {
      setServer({ error: error instanceof Error ? error.message : "Something went wrong. Your message is still here; try again." });
    } finally {
      setPending(false);
    }
    if (target) refocus.current = target;
  };

  return (
    <section data-slot="contact" aria-labelledby={heading} className={cn("mx-auto grid w-full max-w-5xl gap-10 px-4 py-12 sm:px-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.25fr)]", className)}>
      <div className="grid content-start gap-4">
        <h2 id={heading} className="text-2xl font-semibold tracking-tight">
          {title}
        </h2>
        {description && <p className="max-w-sm text-sm text-muted-foreground">{description}</p>}
        {details && details.length > 0 && (
          <dl className="mt-2 grid gap-4 text-sm">
            {details.map((d) => (
              <div key={d.label}>
                <dt className="text-xs text-muted-foreground">{d.label}</dt>
                <dd className="mt-0.5">
                  {d.href ? (
                    <a href={d.href} className="rounded-control underline underline-offset-4 outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring">
                      {d.value}
                    </a>
                  ) : (
                    d.value
                  )}
                </dd>
              </div>
            ))}
          </dl>
        )}
      </div>
      <div className="rounded-overlay border border-border bg-background p-5 sm:p-6">
        {sent ? (
          <div ref={thanks} tabIndex={-1} role="status" className="grid justify-items-start gap-3 outline-none">
            <CheckCircle2 aria-hidden="true" className="size-6 text-success" />
            <h3 className="text-lg font-semibold">{successTitle}</h3>
            <p className="text-sm text-muted-foreground">{successText}</p>
            <Button
              variant="secondary"
              size="sm"
              onClick={() => {
                setSent(false);
                setValues({ name: "", email: "", topic: topics?.[0] ?? "", message: "", website: "" });
                setTouched({ name: false, email: false, message: false });
              }}
            >
              Send another message
            </Button>
          </div>
        ) : (
          <form ref={form} noValidate aria-labelledby={heading} onSubmit={submit} className="grid gap-4">
            {server.error && <Alert variant="error" title={server.error} />}
            <div className="grid gap-4 sm:grid-cols-2">
              <Field label="Name" error={errors.name} required>
                {(control) => <Input {...control} name="name" autoComplete="name" value={values.name} disabled={pending} onChange={(e) => setValues({ ...values, name: e.target.value })} onBlur={() => setTouched((t) => ({ ...t, name: true }))} />}
              </Field>
              <Field label="Email" error={errors.email} required>
                {(control) => (
                  <Input {...control} name="email" type="email" inputMode="email" autoComplete="email" autoCapitalize="none" spellCheck={false} value={values.email} disabled={pending} onChange={(e) => setValues({ ...values, email: e.target.value })} onBlur={() => setTouched((t) => ({ ...t, email: true }))} />
                )}
              </Field>
            </div>
            {topics && topics.length > 0 && (
              <Field label="Topic">
                {(control) => (
                  <SelectMenu {...control} name="topic" value={values.topic} disabled={pending} onValueChange={(topic) => setValues({ ...values, topic })} options={topics.map((t) => ({ value: t, label: t }))} />
                )}
              </Field>
            )}
            <Field label="Message" error={errors.message} required description={`${values.message.trim().length} characters`}>
              {(control) => <Textarea {...control} name="message" rows={5} value={values.message} disabled={pending} onChange={(e) => setValues({ ...values, message: e.target.value })} onBlur={() => setTouched((t) => ({ ...t, message: true }))} />}
            </Field>
            {/* Hidden from people; automated forms fill it in. */}
            <div aria-hidden="true" className="absolute -left-[9999px] h-0 w-0 overflow-hidden">
              <label>
                Website
                <input name="website" tabIndex={-1} autoComplete="off" value={values.website} onChange={(e) => setValues({ ...values, website: e.target.value })} />
              </label>
            </div>
            <Button type="submit" loading={pending} className="justify-self-start">
              {pending ? "Sending…" : "Send message"}
            </Button>
          </form>
        )}
      </div>
    </section>
  );
}

import { CircleCheck, CircleX, Info, LoaderCircle, TriangleAlert } from "lucide-react";
import "./feedback.css";

export type FeedbackVariant = "neutral" | "success" | "warning" | "error";

const icons = {
  neutral: Info,
  success: CircleCheck,
  warning: TriangleAlert,
  error: CircleX,
};

export function FeedbackIcon({
  variant,
  loading = false,
}: {
  variant: FeedbackVariant;
  loading?: boolean;
}) {
  const Icon = loading ? LoaderCircle : icons[variant];
  return (
    <span data-slot="feedback-icon" aria-hidden="true">
      <span data-slot="feedback-symbol" key={loading ? "loading" : variant}>
        <Icon data-slot={loading ? "loading-indicator" : undefined} />
      </span>
    </span>
  );
}

"use client";
import { CircleAlert, CircleCheck, LoaderCircle } from "lucide-react";
import { useId, type ReactNode } from "react";
import { Label } from "./label";
import { cn } from "./lib/cn";
import "./shared/field-message.css";
import "./shared/loading-indicator.css";
import "./field.css";

export type FieldControlProps = {
  id: string;
  "aria-describedby"?: string;
  "aria-invalid"?: true;
  "aria-required"?: true;
};

export const isEmail = (value: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());

/**
 * A label, a control and one message line wired together for assistive
 * technology. Hint, async status and error share the same reserved line and
 * rewrite it in place, so validation never pushes the next field down.
 */
export function Field({
  label,
  description,
  error,
  status,
  statusTone = "pending",
  count,
  required,
  optional,
  action,
  className,
  children,
}: {
  label: string;
  /** Hint shown on the message line until a status or error replaces it. */
  description?: ReactNode;
  /** Replaces the hint and is announced when it appears. */
  error?: string;
  /** An async result such as “Checking availability…” or “Available”. */
  status?: string;
  statusTone?: "pending" | "success";
  /** Right-aligned counter on the message line, e.g. “6 / 40”. */
  count?: string;
  required?: boolean;
  /** Adds "(optional)" after the label. */
  optional?: boolean;
  /** Something aligned with the label, such as a "Forgot password?" link. */
  action?: ReactNode;
  className?: string;
  children: (props: FieldControlProps) => ReactNode;
}) {
  const id = useId();
  const message = `${id}-message`;
  const hasMessage = Boolean(error || status || description || count);
  const tone = error ? "error" : status ? statusTone : "hint";
  return (
    <div data-slot="field" className={cn("grid gap-1.5", className)}>
      <div className="flex items-baseline justify-between gap-3">
        <Label htmlFor={id}>
          {label}
          {optional && <span className="ml-1 font-normal text-muted-foreground">(optional)</span>}
        </Label>
        {action}
      </div>
      {children({
        id,
        "aria-describedby": hasMessage ? message : undefined,
        "aria-invalid": error ? true : undefined,
        "aria-required": required ? true : undefined,
      })}
      <p id={message} data-slot="field-message" data-tone={tone} aria-live={error ? "assertive" : "polite"} role={error ? "alert" : undefined}>
        {tone === "error" && <CircleAlert aria-hidden="true" />}
        {tone === "success" && <CircleCheck aria-hidden="true" />}
        {tone === "pending" && <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />}
        <span data-slot="field-error" className="min-w-0 flex-1">{error ?? status ?? description}</span>
        {count && <span data-slot="field-count">{count}</span>}
      </p>
    </div>
  );
}

import type { ComponentProps, ReactNode } from "react";
import { cn } from "./lib/cn";
import "./shared/input.css";
import "./shared/input-2.css";
import "./shared/input-group.css";
import "./input.css";

const fieldText =
  "w-full min-w-0 text-base text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed md:text-sm";

export type InputProps = ComponentProps<"input"> & {
  /** Fixed text or an icon before the value, e.g. "caliper.app/". */
  leading?: ReactNode;
  /** Text, an icon or a status after the value, e.g. a spinner or a count. */
  trailing?: ReactNode;
};

/**
 * A recessed text field. Fields sit slightly below the paper (an inner shade
 * and a 3:1 ring); buttons stand on it, so what you fill and what you press
 * never look alike.
 */
export function Input({ className, leading, trailing, ...props }: InputProps) {
  if (leading === undefined && trailing === undefined) {
    return (
      <input
        data-slot="input"
        className={cn("flex h-[var(--control-height)] rounded-button px-3", fieldText, className)}
        {...props}
      />
    );
  }
  return (
    <span
      data-slot="input-group"
      data-disabled={props.disabled || undefined}
      data-invalid={props["aria-invalid"] === true || props["aria-invalid"] === "true" || undefined}
      data-readonly={props.readOnly || undefined}
      className={cn("flex h-[var(--control-height)] w-full min-w-0 items-center gap-2 rounded-button px-3", className)}
    >
      {leading !== undefined && <span data-slot="input-affix">{leading}</span>}
      <input data-slot="input-bare" className={cn("h-full flex-1 bg-transparent", fieldText)} {...props} />
      {trailing !== undefined && <span data-slot="input-trailing">{trailing}</span>}
    </span>
  );
}

import type { ComponentProps } from "react";
import { cn } from "./lib/cn";

export function Label({ className, ...props }: ComponentProps<"label">) {
  return (
    <label
      data-slot="label"
      className={cn(
        "inline-block max-w-full text-sm leading-5 font-medium [overflow-wrap:anywhere]",
        className,
      )}
      {...props}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as Popover from "@radix-ui/react-popover";
import { Check, ChevronsUpDown } from "lucide-react";
import {
  useEffect,
  useId,
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
  type ReactNode,
  type Ref,
} from "react";
import { cn } from "./lib/cn";
import "./shared/select.css";
import "./shared/input-2.css";
import "./select-menu.css";

export type SelectMenuOption = {
  value: string;
  label: string;
  /** Short identifier shown in mono at the end of the row, e.g. "eu-central-1". */
  code?: string;
  /** A 16px mark before the label, e.g. a network dot or a person's initials. */
  icon?: ReactNode;
  disabled?: boolean;
};

const ROW = 36;
const PAD = 4;

function useCoarsePointer() {
  const [coarse, setCoarse] = useState(false);
  useEffect(() => {
    const query = window.matchMedia("(pointer: coarse)");
    const update = () => setCoarse(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  return coarse;
}

/**
 * A select whose list opens with the chosen option lying exactly over the
 * trigger text, so the eye never jumps. On touch screens it is the platform
 * picker. A hidden input carries the value in native forms.
 */
export function SelectMenu({
  options,
  value: controlled,
  defaultValue,
  onValueChange,
  placeholder = "Choose…",
  name,
  disabled,
  size = "md",
  variant = "field",
  className,
  ref,
  ...aria
}: {
  options: readonly SelectMenuOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  /** Submitted with the form. */
  name?: string;
  disabled?: boolean;
  /** sm is 32px for toolbars, filters and table rows; md follows the control height. */
  size?: "sm" | "md";
  /** ghost drops the field ring, for a select inside a composed control (a currency in a money field). */
  variant?: "field" | "ghost";
  className?: string;
  /** The trigger (or, on touch screens, the native select), e.g. for a dialog's first focus. */
  ref?: Ref<HTMLButtonElement | HTMLSelectElement>;
} & Pick<ComponentProps<"button">, "id" | "aria-label" | "aria-labelledby" | "aria-describedby" | "aria-invalid" | "aria-required">) {
  const listId = useId();
  const coarse = useCoarsePointer();
  const [inner, setInner] = useState(defaultValue);
  const value = controlled ?? inner;
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const [offset, setOffset] = useState(0);
  const trigger = useRef<HTMLButtonElement>(null);
  const list = useRef<HTMLDivElement>(null);
  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === value));
  const selected = options.find((option) => option.value === value);

  // If the change handler moves focus on (e.g. into a reply box), leave it there when the list closes.
  const keepFocus = useRef(false);
  // A form may disable the trigger while it saves the choice. Focus cannot return to a disabled button,
  // so it returns as soon as the trigger is enabled again, unless the reader has moved on by then.
  const refocus = useRef(false);
  useEffect(() => {
    if (disabled || !refocus.current) return;
    refocus.current = false;
    const now = document.activeElement;
    if (!now || now === document.body) trigger.current?.focus();
  }, [disabled]);
  function choose(next: string) {
    if (controlled === undefined) setInner(next);
    onValueChange?.(next);
    const now = document.activeElement;
    keepFocus.current = !!now && now !== document.body && now !== trigger.current && !list.current?.contains(now);
  }

  function openList(nextOpen: boolean) {
    if (nextOpen && trigger.current) {
      // Lay the selected row over the trigger, unless that would leave the viewport.
      const rect = trigger.current.getBoundingClientRect();
      const above = PAD + selectedIndex * ROW;
      const fits = rect.top - above > 8 && rect.top - above + options.length * ROW + PAD * 2 < window.innerHeight - 8;
      setOffset(fits ? -(rect.height + above) - (ROW - rect.height) / 2 : 6);
      setActive(selectedIndex);
    }
    setOpen(nextOpen);
  }

  function move(delta: number) {
    let next = active;
    for (let step = 0; step < options.length; step += 1) {
      next = Math.min(options.length - 1, Math.max(0, next + delta));
      if (!options[next].disabled) break;
    }
    setActive(next);
  }

  function onListKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === "ArrowDown") move(1);
    else if (event.key === "ArrowUp") move(-1);
    else if (event.key === "Home") setActive(options.findIndex((option) => !option.disabled));
    else if (event.key === "End") setActive(options.length - 1 - [...options].reverse().findIndex((option) => !option.disabled));
    else if (event.key === "Enter" || event.key === " ") {
      const option = options[active];
      if (option && !option.disabled) {
        choose(option.value);
        setOpen(false);
      }
    } else if (event.key === "Tab") setOpen(false);
    else if (/^\S$/.test(event.key)) {
      const start = (active + 1) % options.length;
      const order = [...options.slice(start), ...options.slice(0, start)];
      const hit = order.find((option) => !option.disabled && option.label.toLowerCase().startsWith(event.key.toLowerCase()));
      if (hit) setActive(options.indexOf(hit));
    } else return;
    event.preventDefault();
  }

  useEffect(() => {
    if (!open) return;
    list.current?.querySelector<HTMLElement>(`[data-index="${active}"]`)?.scrollIntoView({ block: "nearest" });
  }, [active, open]);

  if (coarse) {
    return (
      <span data-slot="select-menu-native" data-size={size} data-variant={variant} className={cn("relative block", className)}>
        <select
          ref={ref as Ref<HTMLSelectElement>}
          data-slot="select"
          {...aria}
          name={name}
          disabled={disabled}
          value={value ?? ""}
          onChange={(event) => choose(event.target.value)}
          className={cn(
            "block w-full min-w-0 appearance-none text-base text-foreground outline-none",
            size === "sm" ? "h-8 rounded-control pr-8 pl-2.5" : "h-[var(--control-height)] rounded-button pr-9 pl-3",
          )}
        >
          {!selected && <option value="" disabled>{placeholder}</option>}
          {options.map((option) => (
            <option key={option.value} value={option.value} disabled={option.disabled}>
              {option.label}
              {option.code ? ` · ${option.code}` : ""}
            </option>
          ))}
        </select>
        <ChevronsUpDown aria-hidden="true" className={cn("pointer-events-none absolute top-1/2 size-4 -translate-y-1/2 text-muted-foreground", size === "sm" ? "right-2.5" : "right-3")} />
      </span>
    );
  }

  return (
    <Popover.Root open={open} onOpenChange={openList}>
      <Popover.Trigger asChild>
        <button
          ref={(node) => {
            trigger.current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) (ref as { current: HTMLButtonElement | HTMLSelectElement | null }).current = node;
          }}
          type="button"
          data-slot="select-menu"
          data-size={size}
          data-variant={variant}
          role="combobox"
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-controls={open ? listId : undefined}
          disabled={disabled}
          {...aria}
          onKeyDown={(event) => {
            if (event.key === "ArrowDown" || event.key === "ArrowUp") {
              event.preventDefault();
              openList(true);
            }
          }}
          className={cn(
            "flex w-full min-w-0 items-center justify-between gap-2 text-left text-foreground outline-none disabled:cursor-not-allowed",
            size === "sm" ? "h-8 rounded-control px-2.5 text-[13px]" : "h-[var(--control-height)] rounded-button px-3 text-base md:text-sm",
            className,
          )}
        >
          <span className={cn("flex min-w-0 items-center gap-2", !selected && "text-muted-foreground")}>
            {selected?.icon && <span data-slot="select-menu-icon" aria-hidden="true">{selected.icon}</span>}
            <span className="truncate">{selected ? selected.label : placeholder}</span>
            {selected?.code && <span data-slot="select-menu-code" className="shrink-0">{selected.code}</span>}
          </span>
          <ChevronsUpDown aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </Popover.Trigger>
      {name && <input type="hidden" name={name} value={value ?? ""} />}
      <Popover.Portal>
        <Popover.Content
          side="bottom"
          align="start"
          sideOffset={offset}
          alignOffset={-28}
          avoidCollisions={offset > 0}
          onOpenAutoFocus={(event) => {
            event.preventDefault();
            keepFocus.current = false;
            list.current?.focus();
          }}
          onCloseAutoFocus={(event) => {
            if (keepFocus.current) event.preventDefault();
            else if (trigger.current?.disabled) {
              event.preventDefault();
              refocus.current = true;
            }
          }}
          data-slot="select-menu-content"
          style={{ width: "calc(var(--radix-popover-trigger-width) + 36px)", transformOrigin: `50% ${PAD + selectedIndex * ROW + ROW / 2}px` }}
        >
          <div
            ref={list}
            id={listId}
            role="listbox"
            tabIndex={-1}
            aria-labelledby={aria["aria-labelledby"]}
            aria-label={aria["aria-label"]}
            aria-activedescendant={`${listId}-${active}`}
            onKeyDown={onListKeyDown}
            className="max-h-[calc(8*36px+8px)] overflow-y-auto p-1 outline-none"
          >
            {options.map((option, index) => (
              <div
                key={option.value}
                id={`${listId}-${index}`}
                role="option"
                data-index={index}
                aria-selected={option.value === value}
                aria-disabled={option.disabled || undefined}
                data-active={index === active}
                data-slot="select-menu-option"
                onPointerMove={() => !option.disabled && setActive(index)}
                onClick={() => {
                  if (option.disabled) return;
                  choose(option.value);
                  setOpen(false);
                }}
              >
                <span className="grid size-4 place-items-center">{option.value === value && <Check aria-hidden="true" className="size-4" />}</span>
                {option.icon && <span data-slot="select-menu-icon" aria-hidden="true">{option.icon}</span>}
                <span className="min-w-0 flex-1 truncate">{option.label}</span>
                {option.code && <span data-slot="select-menu-code">{option.code}</span>}
              </div>
            ))}
          </div>
        </Popover.Content>
      </Popover.Portal>
    </Popover.Root>
  );
}

